async def parse_list(page):
    rows = await page.query_selector_all('table tbody tr')
    for row in rows:
        title = await row.query_selector_eval('td:nth-child(1)', 'el => el.textContent.trim()')
        detail_link = await row.query_selector_eval('a[href^="https://www.ncbi.nlm.nih.gov/gap/"]', 'el => el.href')
        yield {'title': title, 'detail_link': detail_link}
